starterCode:
SELECT e.name, ... AS total_payout
FROM Employee e
LEFT JOIN Bonus b ON e.empId = b.empId;

solutionSQL:
SELECT e.name, e.salary + IFNULL(b.bonus, 0) AS total_payout
FROM Employee e
LEFT JOIN Bonus b ON e.empId = b.empId;

